use crate::stage9::{OtpSecurityError,otp_value_to_security_level};use crate::stage13::SecureBootOtp;use crate::stage14::{SecureBootPolicy,ensure_and_verify_secure_boot};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct SecurityPolicyReport{pub secure_boot:SecureBootPolicy,pub security_level:u8}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum SecurityPolicyError<E>{Otp(E),UnsupportedMode}
pub fn evaluate_security_policy<I:SecureBootOtp>(io:&mut I,security_bytes:[u8;2],mode:u8)->Result<SecurityPolicyReport,SecurityPolicyError<I::Error>>{let secure_boot=ensure_and_verify_secure_boot(io).map_err(SecurityPolicyError::Otp)?;let security_level=otp_value_to_security_level(security_bytes,mode).map_err(|OtpSecurityError::UnsupportedMode|SecurityPolicyError::UnsupportedMode)?;Ok(SecurityPolicyReport{secure_boot,security_level})}
#[cfg(test)]mod tests{use super::*;struct O{v:u8}impl SecureBootOtp for O{type Error=();fn read_secure_byte(&mut self,_:u16)->Result<u8,()>{Ok(self.v)}fn write_secure_byte(&mut self,_:u16,v:u8)->Result<(),()>{self.v=v;Ok(())}}#[test]fn policy(){let mut o=O{v:0};let r=evaluate_security_policy(&mut o,[0x30,0],1).unwrap();assert_eq!(r.security_level,2);assert_eq!(r.secure_boot,SecureBootPolicy::EnabledNow);}}
